//! Actions-only actual current AccountManager, committed IM body, independent
//! matched UserEntry TCP/TLS/Common, purpose Group READ/WRITE and all IO Joins.
use super::*;
use super::super::super::super as n;
async fn bounded<F:std::future::Future>(f:F)->F::Output{tokio::time::timeout(Duration::from_secs(12),f).await.expect("original account peer budget")}
fn message()->Vec<u8>{let mut b=Writer::new();b.i64(7).unwrap();b.i64(1).unwrap();b.bytes(b"fixture-sender").unwrap();b.bytes(b"Text").unwrap();b.bytes(br#"{"text":"explicit recipient read body"}"#).unwrap();b.properties(&[]).unwrap();b.properties(&[]).unwrap();let mut args=Writer::versioned().unwrap();args.bytes(n::im_data::MORE_MESSAGE_KIND).unwrap();args.properties(&[RpcProperty{key:b"Box",value:b"P2P/1_2"}]).unwrap();args.bytes(b.finish().expose_to_transport()).unwrap();let e=encode_request(91,&[RpcProperty{key:b"id",value:b"MessageReceiver"},RpcProperty{key:b"__magic",value:&[9,1]}],n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),args.finish().expose_to_transport()).unwrap();let mut p=vec![0];p.extend_from_slice(e.expose_to_transport());p}
async fn poll(peer:&mut CommonPeer,call:&n::rpc_envelope::RpcRequest<'_>){assert_eq!(call.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(call.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let data=n::rpc_batch::read_payload(&mut r).unwrap();let seq=data.requests.keys().copied().max();peer.send(&[reply(call.call_id,&super::super::tests::swap_result(seq,true,data.fields))]).await;}
async fn next(peer:&mut CommonPeer,method:&str)->Vec<u8>{loop{let p=peer.next().await.unwrap();let call=decode_request(&p[1..]).unwrap();if call.method==method.as_bytes(){return p;}poll(peer,&call).await;}}
fn status()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();w.properties(&[RpcProperty{key:n::im_status::LATEST,value:b"9"}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn aid_result(mode:u8)->Vec<u8>{let mut w=Writer::new();w.boolean(mode!=2).unwrap();w.u32(1).unwrap();w.bytes(if mode==1{b"9_9"}else{b"1_2"}).unwrap();w.bytes(b"phone").unwrap();w.bytes(b"+12345").unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn config(root:&str,port:u16)->n::account_config::AccountConfig{let c=bootstrap_account_config(root,port);let mut v:serde_json::Value=serde_json::from_slice(&c.encode_private().unwrap()).unwrap();v["config"]["profile"]["incoming"]=serde_json::Value::Null;v["config"]["profile"]["native_receivers"]=serde_json::json!({"im_messages":{"notification_timeout_ms":3000}});v["config"]["profile"]["client_ex"]=serde_json::json!(true);v["config"]["profile"]["im_user_read"]=serde_json::json!({"mark_read":true});n::account_config::AccountConfig::decode_private(&serde_json::to_vec(&v).unwrap()).unwrap()}
async fn scenario(mode:u8){
    let cert=Certificates::generate("IP:127.0.0.1");let front=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=front.local_addr().unwrap().port();let boot=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let main=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let auxiliary=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let ports=[boot.local_addr().unwrap().port(),main.local_addr().unwrap().port(),auxiliary.local_addr().unwrap().port()];let server=cert.server_config(&TLS13);let source_server=server.clone();let main_server=server.clone();let(sent,submitted)=oneshot::channel();let(respond,ready)=oneshot::channel();
    let relay=tokio::spawn(async move{bounded(async move{let mut joins=Vec::new();for target in ports{let(mut a,_)=front.accept().await.unwrap();let mut b=tokio::net::TcpStream::connect((std::net::Ipv4Addr::LOCALHOST,target)).await.unwrap();joins.push(tokio::spawn(async move{let _=tokio::io::copy_bidirectional(&mut a,&mut b).await;}));}for j in joins{j.await.unwrap();}}).await});
    let source=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(boot,source_server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_bootstrap::GET_APP_CONFIGS_METHOD.as_bytes());peer.send(&[reply(r.call_id,&bootstrap_user_entry())]).await;peer.no_more_common().await;}).await});
    let sdk=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(main,main_server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_login::LOGIN_SESSION_METHOD.as_bytes());peer.send(&[reply(r.call_id,&login_result_for_account())]).await;let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"4");peer.send(&[message()]).await;loop{let p=peer.next().await.unwrap();if p[0]==1{assert_eq!(decode_reply(&p[1..]).unwrap().call_id,91);break;}let r=decode_request(&p[1..]).unwrap();poll(&mut peer,&r).await;}
        if mode==0||mode==3||mode==4{let p=next(&mut peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");peer.send(&[reply(r.call_id,&status())]).await;let p=next(&mut peer,n::im_user_read_data::MARK_READ_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"1_2");assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.bytes().unwrap(),b"P:P_UDMR-N");assert_eq!(a.bytes().unwrap(),b"7");assert!(a.i64().unwrap()>0);a.finish().unwrap();sent.send(()).unwrap();if mode==4{ready.await.unwrap();assert!(peer.next().await.is_none(),"unknown original WRITE cannot send unhosting/logout or replay on retired IO");return;}else{peer.send(&[reply(r.call_id,if mode==3{&[0;6]}else{&[0,1,0,0,0,0]})]).await;}}
        let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"3");logout_peer(peer).await;
    }).await});
    let resolver=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(auxiliary,server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::user_entry_data::AID_TO_UID_METHOD.as_bytes());assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"prefix/UserEntry");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");peer.send(&[reply(r.call_id,&aid_result(mode))]).await;peer.no_more_common().await;}).await});
    let temp=n::account_test_support::TempDatabase::new();let manager=n::account_runtime::AccountManager::new(temp.database.clone());let created=manager.create(config(&cert.root,port),100).await.unwrap();let line=created.account.line_id.clone();manager.start(&line,1,100).await.unwrap();let id=bounded(async{loop{let rows=manager.im_messages(&line,16).unwrap();if let Some(row)=rows.first(){break row.id;}tokio::task::yield_now().await;}}).await;
    let uri="[phone:+12345@account-domain.invalid]";let nonce="a".repeat(32);assert_eq!(manager.mark_im_user_read_via_recipient(&line,2,id,&nonce,uri,true).await.err(),Some("app_account_revision_conflict"));assert_eq!(manager.mark_im_user_read_via_recipient(&line,1,id,&nonce,uri,false).await.err(),Some("app_account_im_user_read_consent_required"));let mut operation=Box::pin(manager.mark_im_user_read_via_recipient(&line,1,id,&nonce,uri,true));
    if mode==4{bounded(async{tokio::select!{_=submitted=>(),v=&mut operation=>panic!("write returned before actual submission: {v:?}")}}).await;drop(operation);respond.send(()).unwrap();}else{let result=bounded(operation).await;if mode==1||mode==2{assert_eq!(result.err(),Some("app_account_im_user_read_recipient_unconfirmed"));assert!(manager.im_user_read_history(&line,16).unwrap().is_empty());}else{let view=result.unwrap();assert_eq!(view.state,if mode==3{"rejected"}else{"confirmed"});let same=manager.mark_im_user_read_via_recipient(&line,1,id,&nonce,uri,true).await.unwrap();assert_eq!(same.state,view.state);assert_eq!(manager.mark_im_user_read_via_recipient(&line,1,id,&nonce,"[phone:+67890@account-domain.invalid]",true).await.err(),Some("app_account_im_user_read_nonce_conflict"));}drop(respond);}
    if mode==4{let state=manager.im_user_read_history(&line,16).unwrap();assert_eq!(state[0].state,"uncertain");assert!(manager.mark_im_user_read_via_recipient(&line,1,id,&"b".repeat(32),uri,true).await.is_err(),"a new caller nonce cannot regain the retired original SDK/WRITE");}
    if mode==4{bounded(async{while manager.get(&line,100).await.unwrap().phase!="disconnected"{tokio::task::yield_now().await;}}).await;}
    let stopped=manager.stop(&line,1,100).await.unwrap();assert!(!stopped.io_cleanup_required);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(manager.shutdown_all().await,0);bounded(async{source.await.unwrap();sdk.await.unwrap();resolver.await.unwrap();relay.await.unwrap();}).await;
}
#[tokio::test]async fn user_read_recipient_actual_current_account_uid_match_then_original_group_write_and_all_joins(){Box::pin(scenario(0)).await;}
#[tokio::test]async fn user_read_recipient_wrong_resolved_uid_cannot_refresh_or_write_another_message(){Box::pin(scenario(1)).await;}
#[tokio::test]async fn user_read_recipient_negative_original_lookup_cannot_become_a_user_write_permission(){Box::pin(scenario(2)).await;}
#[tokio::test]async fn user_read_recipient_known_rejected_write_is_not_replayed_for_same_nonce(){Box::pin(scenario(3)).await;}
#[tokio::test]async fn user_read_recipient_full_submission_cancel_preserves_unknown_and_blocks_new_recipient_nonce(){Box::pin(scenario(4)).await;}
